SET @prov_c='%s';
SET @id:= '%s';
SET @cat_id := '%s';
SET @send :=  IF((SELECT active FROM sys_report WHERE cat_id = @cat_id and id = @id )=1,0,2);
SET @b_year:=(SELECT yearprocess FROM pk_byear LIMIT 1);
SET @start_d:=concat(@b_year-1,'1001');
SET @end_d:=concat(@b_year,'0930');

CREATE TABLE IF NOT EXISTS s_opioid_acp_w (
  id varchar(32) NOT NULL,
  hospcode varchar(5) NOT NULL,
  areacode varchar(8) NOT NULL,
  flag_sent varchar(1) DEFAULT NULL,
  date_com varchar(14) DEFAULT NULL,
  b_year varchar(4) NOT NULL,
	target int(10) DEFAULT 0,
	result int(10) DEFAULT 0,
PRIMARY KEY (id,hospcode,areacode,b_year),
	KEY (hospcode),
	KEY (areacode),
	KEY (b_year)
) ENGINE=MyISAM DEFAULT CHARSET=utf8;

DELETE FROM s_opioid_acp_w  WHERE id=@id AND b_year=(@b_year+543);

DROP TEMPORARY TABLE IF EXISTS tmp_z718;
CREATE TEMPORARY TABLE IF NOT EXISTS tmp_z718(
PRIMARY KEY(hospcode,cid),
KEY(hospcode,cid),
KEY (cid)
) ENGINE=myisam IGNORE AS 
 SELECT HOSPCODE,CID
 FROM tmp_diag_opd  
WHERE SUBSTR(DIAGCODE,1,4) in('Z718');

INSERT IGNORE INTO tmp_z718 (
SELECT HOSPCODE,CID 
FROM tmp_diag_ipd  
WHERE SUBSTR(DIAGCODE,1,4) in('Z718')
);

INSERT IGNORE INTO s_opioid_acp_w  
(
SELECT
@id,h.hoscode,CONCAT(h.provcode,h.distcode,h.subdistcode,SUBSTR(CONCAT('00',h.mu),-2)) areacode
,@send,DATE_FORMAT(now(),'%Y%m%d%H%i') as d_com,@b_year+543 as b_year
,COUNT(DISTINCT CONCAT(p.HOSPCODE,'-',p.PID)) z515
,COUNT(DISTINCT CONCAT(z.HOSPCODE,'-',z.CID)) z718
FROM tmp_pallitive  t
INNER JOIN t_person_db p  ON t.CID=p.CID AND INSTR(t.g_code,concat('"HOSPCODE":"',p.HOSPCODE))
INNER JOIN chospital h ON p.HOSPCODE=h.hoscode AND h.hostype IN(5,6,7,11,12,15)
 LEFT JOIN tmp_z718 z ON p.HOSPCODE=z.HOSPCODE AND t.CID=z.CID
WHERE  p.NATION in(99) 
GROUP BY h.hoscode
);
